{"src/runTasks.mjs":"/** tasks是无参数异步函数数组，concurrency是并发上限；返回Promise。 */
export function runTasks(tasks, concurrency) {
  return new Promise((resolve, reject) => {
    if (!Array.isArray(tasks)) {
      reject(new TypeError('tasks must be an array of functions'));
      return;
    }

    const total = tasks.length;
    if (total === 0) {
      resolve([]);
      return;
    }

    if (
      typeof concurrency !== 'number' ||
      !Number.isInteger(concurrency) ||
      concurrency <= 0
    ) {
      reject(
        new RangeError('concurrency must be a positive integer')
      );
      return;
    }

    const results = new Array(total);
    let nextIndex = 0;
    let completed = 0;
    let settled = false;

    const fail = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    const launchNext = () => {
      if (settled) return;
      if (nextIndex >= total) return;

      const index = nextIndex++;
      let taskResult;

      try {
        taskResult = tasks[index]();
      } catch (error) {
        fail(error);
        return;
      }

      Promise.resolve(taskResult).then(
        (value) => {
          if (settled) return;
          results[index] = value;
          completed += 1;

          if (completed === total) {
            settled = true;
            resolve(results);
            return;
          }

          launchNext();
        },
        (error) => {
          fail(error);
        }
      );
    };

    const initial = Math.min(concurrency, total);
    for (let i = 0; i < initial; i += 1) {
      launchNext();
    }
  });
}
